import java.util.*;

class Solution {
  public boolean wordPatternMatch(String pattern, String s) {
    return match(pattern, 0, s, 0, new HashMap<>(), new HashSet<>());
  }

  private boolean match(String p, int i, String s, int j, Map<Character, String> map, Set<String> used) {
    if (i == p.length()) return j == s.length();
    char c = p.charAt(i);
    String w = map.get(c);
    if (w != null) return s.startsWith(w, j) && match(p, i + 1, s, j + w.length(), map, used);
    for (int end = j + 1; end <= s.length(); end++) {
      String cand = s.substring(j, end);
      if (used.contains(cand)) continue;
      map.put(c, cand);
      used.add(cand);
      if (match(p, i + 1, s, end, map, used)) return true;
      map.remove(c);
      used.remove(cand);
    }
    return false;
  }
}
